            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows will Center deinstallieren. Hier abschlie\u00DFen, oder B dr\u00FCcken und alles behalten.",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows konnte die Paketdatei nicht \u00F6ffnen. Das liegt nicht am Paket selbst \u2014 der Bereitstellungsdienst (l\u00E4uft als SYSTEM) konnte sie nicht lesen. Installiere aus einem Ordner au\u00DFerhalb deines Benutzerprofils und pr\u00FCfe, ob Gaming Services in Ordnung ist.",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows konnte das Paket aus diesem Ordner nicht \u00F6ffnen. Neuer Versuch von einem systemweiten Ort\u2026",
            ["Windows file picker"] = "Windows-Dateiauswahl",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). This cannot be undone \u2014 take a backup first if unsure."] = "Setzt jede ClawTweaks-Einstellung zur\u00FCck (alle Profile, L\u00FCfterkurven, TDP, Controller). Das l\u00E4sst sich nicht r\u00FCckg\u00E4ngig machen \u2014 im Zweifel vorher ein Backup anlegen.",
            ["Work down the list. Each step is optional except the last."] = "Arbeite die Liste ab. Nur der letzte Schritt ist Pflicht.",
            ["Working\u2026"] = "L\u00E4uft\u2026",
            ["XInput controllers"] = "XInput-Controller",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "Ja, wenn ClawTweaks Controller, L\u00FCfter und LEDs steuern soll.",
            ["Yes, install"] = "Ja, installieren",
            ["Yes, reset everything"] = "Ja, alles zur\u00FCcksetzen",
