            ["The update could not install itself. Try the button below."] = "Das Update konnte sich nicht selbst installieren. Nutze den Knopf unten.",
            ["Installing\u2026"] = "Installiere\u2026",
            ["Install update now"] = "Update jetzt installieren",
            ["Version {0} is still installed for all users, in {1}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "Version {0} ist noch f\u00FCr alle Benutzer installiert, in {1}. Diese Version installiert sich stattdessen in deinen Benutzerordner; die alte wird nicht mehr benutzt \u2014 bleibt aber in Einstellungen \u2192 Apps und im Startmen\u00FC, bis sie entfernt ist, und l\u00E4sst sich dort leicht versehentlich starten.",
            ["A previous version is still installed for all users, in {0}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "Eine fr\u00FChere Version ist noch f\u00FCr alle Benutzer installiert, in {0}. Diese Version installiert sich stattdessen in deinen Benutzerordner; die alte wird nicht mehr benutzt \u2014 bleibt aber in Einstellungen \u2192 Apps und im Startmen\u00FC, bis sie entfernt ist, und l\u00E4sst sich dort leicht versehentlich starten.",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below starts the old version's own uninstaller, so the prompt you see comes from it, about removing itself."] = "Das Entfernen braucht Adminrechte. ClawTweaks Center fragt nie danach \u2014 der Knopf unten startet die Deinstallation der alten Version selbst; die Abfrage, die du siehst, kommt von ihr.",
            ["Scroll"] = "Scrollen",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller still won't start."] = "Das sind Kerneltreiber. Ohne Neustart sieht alles installiert aus, und der virtuelle Controller startet trotzdem nicht.",
            ["Version {0}"] = "Version {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "Das neue ClawTweaks Center braucht keine Adminrechte und installiert sich an einen anderen Ort.",
            ["No Xbox games are registered for this account."] = "F\u00FCr dieses Konto sind keine Xbox-Spiele registriert.",
            ["No ROMs for {0}."] = "Keine ROMs f\u00FCr {0}.",
            ["Cycle"] = "Wechseln",
            ["checking the installed version\u2026"] = "installierte Version wird gepr\u00FCft\u2026",
            ["you have {0}."] = "du hast {0}.",
            ["Requires ClawTweaks {0} or newer"] = "Braucht ClawTweaks {0} oder neuer",
            ["Reset, Backup and Restore need ClawTweaks {0} (or 0.1.8+) \u2014 {1} Update ClawTweaks from \"Update & Release\" first."] = "Reset, Backup und Wiederherstellen brauchen ClawTweaks {0} (oder 0.1.8+) \u2014 {1} Aktualisiere ClawTweaks zuerst unter \u201EUpdate & Release\u201C.",
            ["Unknown error."] = "Unbekannter Fehler.",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "Backup wird wiederhergestellt \u2014 der Helper startet danach neu\u2026",
            ["Restore likely completed"] = "Vermutlich wiederhergestellt",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "Der Helper hat vor der Best\u00E4tigung neu gestartet. \u00D6ffne die Game Bar (Win+G) erneut und pr\u00FCfe deine Profile \u2014 wenn etwas nicht stimmt, stelle das automatische Vorab-Backup wieder her.",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "Diese ZIP hat kein g\u00FCltiges ClawTweaks-Manifest \u2014 der Helper lehnt sie ab, wenn es kein echtes Backup ist.",
            ["Different ClawTweaks version"] = "Andere ClawTweaks-Version",
            ["Supported."] = "Unterst\u00FCtzt.",
            ["Recognized, but not supported yet."] = "Erkannt, aber noch nicht unterst\u00FCtzt.",
            ["Not a recognized MSI Claw \u2014 installing here is untested."] = "Keine erkannte MSI Claw \u2014 eine Installation hier ist ungetestet.",
            ["Install the missing prerequisites"] = "Fehlende Voraussetzungen installieren",
            ["Download each one from the vendor and run their installer, then re-check."] = "Lade jedes beim Hersteller herunter, f\u00FChre den Installer aus und pr\u00FCfe dann erneut.",
            ["Re-check and continue"] = "Erneut pr\u00FCfen und fortfahren",
            ["Re-check tools"] = "Tools erneut pr\u00FCfen",
            ["Trust the ClawTweaks signing certificate"] = "Dem ClawTweaks-Signaturzertifikat vertrauen",
            ["ClawTweaks is signed with its own certificate, and Windows only installs a package whose certificate it trusts. You only have to do this once \u2014 every future build uses the same one."] = "ClawTweaks ist mit einem eigenen Zertifikat signiert, und Windows installiert nur Pakete, deren Zertifikat es vertraut. Das ist nur einmal n\u00F6tig \u2014 jeder k\u00FCnftige Build nutzt dasselbe.",
            ["The certificate was imported for your user account instead of the local machine. Windows only consults the machine store when installing a package, so this has no effect. Run the import again and pick \"Local Machine\" on the first page."] = "Das Zertifikat wurde f\u00FCr dein Benutzerkonto statt f\u00FCr den lokalen Computer importiert. Windows liest beim Installieren eines Pakets nur den Computerspeicher, das hat also keine Wirkung. Starte den Import erneut und w\u00E4hle auf der ersten Seite \u201ELokaler Computer\u201C.",
            ["The certificate landed in \"Trusted Root Certification Authorities\". That is both more than ClawTweaks needs \u2014 it would make this certificate a trust anchor for anything, not just this package \u2014 and still not where Windows looks. Remove it from there and import it into \"Trusted People\" instead."] = "Das Zertifikat ist in \u201EVertrauensw\u00FCrdige Stammzertifizierungsstellen\u201C gelandet. Das ist mehr, als ClawTweaks braucht \u2014 es w\u00FCrde dieses Zertifikat zum Vertrauensanker f\u00FCr alles machen, nicht nur f\u00FCr dieses Paket \u2014 und trotzdem nicht dort, wo Windows nachsieht. Entferne es dort und importiere es stattdessen in \u201EVertrauensw\u00FCrdige Personen\u201C.",
            ["Check the certificate and continue"] = "Zertifikat pr\u00FCfen und fortfahren",
            ["Check certificate"] = "Zertifikat pr\u00FCfen",
            ["Installed, but the helper did not appear in time \u2014 open the Game Bar (Win+G) manually."] = "Installiert, aber der Helper ist nicht rechtzeitig erschienen \u2014 \u00F6ffne die Game Bar (Win+G) von Hand.",
            ["Virtual pad"] = "Virtuelles Gamepad",
            ["Virtual controller mode detected"] = "Virtueller Controller-Modus erkannt",
            ["{0} active and running."] = "{0} aktiv und l\u00E4uft.",
            ["HW controller mode detected"] = "HW-Controller-Modus erkannt",
            ["MSI HW Controller active and running."] = "MSI HW-Controller aktiv und l\u00E4uft.",
            ["Claw controller not detected."] = "Claw-Controller nicht erkannt.",
            ["Controller mode unknown"] = "Controller-Modus unbekannt",
            ["The download did not complete. Check your internet connection and try again."] = "Der Download wurde nicht abgeschlossen. Pr\u00FCfe deine Internetverbindung und versuche es erneut.",
            ["This version has no package to download."] = "Diese Version hat kein Paket zum Herunterladen.",
            ["Download complete."] = "Download abgeschlossen.",
            ["The download contains no package file."] = "Der Download enth\u00E4lt keine Paketdatei.",
            ["The downloaded package is incomplete \u2014 its manifest is missing."] = "Das heruntergeladene Paket ist unvollst\u00E4ndig \u2014 sein Manifest fehlt.",
            ["The downloaded package is not readable."] = "Das heruntergeladene Paket ist nicht lesbar.",
            ["(received {0:N0} of {1:N0} bytes)"] = "({0:N0} von {1:N0} Bytes empfangen)",
            ["The download produced an empty file."] = "Der Download hat eine leere Datei ergeben.",
            ["Click \"Install Certificate\u2026\" on the General tab."] = "Klicke im Reiter \u201EAllgemein\u201C auf \u201EZertifikat installieren\u2026\u201C.",
            ["Store Location: choose \"Local Machine\" (not \"Current User\"), then Next. Windows asks for administrator rights here \u2014 that prompt comes from Windows itself."] = "Speicherort: \u201ELokaler Computer\u201C w\u00E4hlen (nicht \u201EAktueller Benutzer\u201C), dann Weiter. Windows fragt hier nach Administratorrechten \u2014 diese Abfrage kommt von Windows selbst.",
            ["Choose \"Place all certificates in the following store\", click Browse\u2026"] = "\u201EAlle Zertifikate in folgendem Speicher speichern\u201C w\u00E4hlen, dann Durchsuchen\u2026",
            ["Select \"Trusted People\" \u2014 NOT \"Trusted Root Certification Authorities\"."] = "\u201EVertrauensw\u00FCrdige Personen\u201C w\u00E4hlen \u2014 NICHT \u201EVertrauensw\u00FCrdige Stammzertifizierungsstellen\u201C.",
            ["Next, then Finish. You should see \"The import was successful.\""] = "Weiter, dann Fertig stellen. Es sollte \u201EDer Importvorgang war erfolgreich.\u201C erscheinen.",
            ["Controller probe timed out."] = "Controller-Pr\u00FCfung: Zeit\u00FCberschreitung.",
            ["Controller probe failed: {0}"] = "Controller-Pr\u00FCfung fehlgeschlagen: {0}",
            ["MSI Claw controller not detected (VID_0DB0). Connect/enable the controller, or MSI Center M may have taken it over."] = "MSI Claw-Controller nicht erkannt (VID_0DB0). Controller anschlie\u00DFen/aktivieren \u2014 oder MSI Center M hat ihn \u00FCbernommen.",
            ["MSI Center M is running. It can fight ClawTweaks for the controller and LED. This is handled after installation."] = "MSI Center M l\u00E4uft. Es kann mit ClawTweaks um Controller und LED konkurrieren. Das wird nach der Installation geregelt.",
            ["Steam's Xbox controller filter driver is present \u2014 a common cause of double input. Check Steam Input settings if you see doubled inputs."] = "Steams Xbox-Controller-Filtertreiber ist vorhanden \u2014 eine h\u00E4ufige Ursache f\u00FCr doppelte Eingaben. Pr\u00FCfe die Steam-Input-Einstellungen, wenn Eingaben doppelt ankommen.",
            ["{0} XInput controllers are currently visible. Two or more while playing = double input."] = "{0} XInput-Controller sind derzeit sichtbar. Zwei oder mehr beim Spielen = doppelte Eingaben.",
            ["Controller healthy \u2014 ready to mount as a virtual pad."] = "Controller in Ordnung \u2014 bereit zum Einbinden als virtuelles Gamepad.",
