            ["Stretch"] = "\u00C9tir\u00E9",
            ["System"] = "Syst\u00E8me",
            ["System language"] = "Langue du syst\u00E8me",
            ["TDP boost"] = "Boost TDP",
            ["Test versions"] = "Versions de test",
            ["That is what makes the extra controller features possible."] = "C'est ce qui rend possibles les fonctions suppl\u00E9mentaires de la manette.",
            ["That key was rejected."] = "Cette cl\u00E9 a \u00E9t\u00E9 refus\u00E9e.",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "Seul ClawTweaks peut r\u00E9initialiser la limite de charge, la courbe du ventilateur et le mode manette. R\u00E9installe-le, puis reviens ici. Tu peux quand m\u00EAme d\u00E9sinstaller Center.",
            ["The controller did not confirm \u2014 check it before you unplug."] = "La manette n'a pas confirm\u00E9 \u2014 v\u00E9rifie-la avant de d\u00E9brancher.",
            ["The device can be restored"] = "L'appareil peut \u00EAtre restaur\u00E9",
            ["The helper did not confirm in time."] = "Le helper n'a pas confirm\u00E9 \u00E0 temps.",
            ["The helper is not answering"] = "Le helper ne r\u00E9pond pas",
            ["The library comes back when the game ends."] = "La biblioth\u00E8que revient \u00E0 la fin du jeu.",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "La manette native doit \u00EAtre propre avant que le mode virtuel puisse fonctionner. En mode virtuel la manette physique est masqu\u00E9e et une manette VIIPER virtuelle est active ; en mode mat\u00E9riel la manette physique est utilis\u00E9e directement.",
            ["The newest changes, least tested"] = "Les changements les plus r\u00E9cents, les moins test\u00E9s",
            ["The old helper exited on its own."] = "L'ancien assistant s'est arr\u00EAt\u00E9 tout seul.",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "Le d\u00E9sinstalleur de l'ancienne version tourne \u2014 confirmez sa demande. Cet avis dispara\u00EEt une fois termin\u00E9 (\u24CE pour actualiser).",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "Le paquet n'a pas pu \u00EAtre supprim\u00E9. Ferme le Game Bar et r\u00E9essaie, ou supprime ClawTweaks depuis Param\u00E8tres \u2192 Applications.",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "La famille de paquets bloquait cette mise \u00E0 jour. Nettoyage puis nouvelle tentative\u2026",
            ["The reset did not finish."] = "La r\u00E9initialisation n'a pas abouti.",
            ["The signing certificate uses Windows' own prompt, once per device."] = "Le certificat passe par la fen\u00EAtre de Windows, une fois par appareil.",
            ["The widget shows what the helper does; it changes nothing by itself."] = "Le widget montre ce que fait le helper ; il ne change rien lui-m\u00EAme.",
            ["The wiki page could not be read. Open it in a browser."] = "La page wiki n'a pas pu \u00EAtre lue. Ouvre-la dans le navigateur.",
            ["This Setup build is outdated"] = "Ce build de Setup est obsol\u00E8te",
            ["This installs an OLDER version than the one installed."] = "Ceci installe une version PLUS ANCIENNE que celle install\u00E9e.",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "Ceci est un build d'ossature sans paquet, il n'y a donc rien \u00E0 installer ici. Dans un vrai bundle, le .msix et le .cer sont \u00E0 c\u00F4t\u00E9 de cet exe.",
            ["This puts the device back and clears your ClawTweaks settings:"] = "Ceci restaure l'appareil et efface tes r\u00E9glages ClawTweaks :",
            ["This removes ClawTweaks Center and closes it."] = "Ceci supprime ClawTweaks Center et le ferme.",
            ["This removes the ClawTweaks app from Windows."] = "Ceci supprime l'app ClawTweaks de Windows.",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "Cela remet TOUS les r\u00E9glages ClawTweaks \u00E0 z\u00E9ro :",
            ["This takes a moment."] = "Cela prend un instant.",
            ["This version can't be installed"] = "Cette version ne peut pas \u00EAtre install\u00E9e",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "Cette version est d\u00E9j\u00E0 install\u00E9e. Ouvrez-la depuis le menu D\u00E9marrer ou le widget ClawTweaks de la Game Bar plut\u00F4t que de relancer ce fichier.",
            ["Timed out"] = "D\u00E9lai d\u00E9pass\u00E9",
            ["Transition to new Center App - Uninstall the old version"] = "Passage au nouveau Center \u2014 d\u00E9sinstaller l'ancienne version",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "Approuve le certificat, installe le paquet, ouvre la Game Bar et attend le helper. Peut \u00EAtre relanc\u00E9 sans risque lors d'une mise \u00E0 jour.",
            ["Turn MSI Center M back on"] = "R\u00E9activer MSI Center M",
            ["Turn on"] = "Activer",
            ["Turning MSI Center M back on\u2026"] = "R\u00E9activation de MSI Center M\u2026",
            ["Uninstall"] = "D\u00E9sinstaller",
            ["Uninstall Center"] = "D\u00E9sinstaller Center",
            ["Update ClawTweaks Center"] = "Mettre \u00E0 jour ClawTweaks Center",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u00C9chec de la mise \u00E0 jour \u2014 voir le journal. R\u00E9essayez, ou lancez en administrateur.",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "Les mises \u00E0 jour ne demandent rien \u2014 la t\u00E2che ne porte pas de version.",
            ["Updating..."] = "Mise \u00E0 jour...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "Utilise plut\u00F4t Uninstall ClawTweaks ici dans Center.",
            ["Verifying the virtual pad\u2026"] = "V\u00E9rification de la manette\u2026",
            ["Vibration"] = "Vibration",
            ["Virtual controller (VIIPER)"] = "Manette virtuelle (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "Manette virtuelle d\u00E9j\u00E0 active \u2014 la manette va bien.",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "La manette virtuelle n'est pas mont\u00E9e \u2014 retour \u00E0 la manette physique.",
            ["Waiting for UAC\u2026"] = "Attente de l'UAC\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "En attente du d\u00E9marrage de l'assistant ClawTweaks. Si la Game Bar s'est ouverte sans rien faire, s\u00E9lectionne le widget ClawTweaks dans son menu et ajoute-le \u2014 un widget absent de la Game Bar ne d\u00E9marre pas l'assistant tout seul.",
            ["Waiting for the virtual controller to settle\u2026"] = "Attente de la stabilisation de la manette\u2026",
            ["What does the background helper do?"] = "Que fait le helper en arri\u00E8re-plan ?",
            ["What happens"] = "Ce qui se passe",
            ["What is the virtual controller for?"] = "\u00C0 quoi sert la manette virtuelle ?",
            ["What's new"] = "Nouveaut\u00E9s",
            ["Where are my settings, and how do I back them up?"] = "O\u00F9 sont mes r\u00E9glages, et comment les sauvegarder ?",
            ["Why does ClawTweaks ask for admin rights?"] = "Pourquoi ClawTweaks demande-t-il les droits admin ?",
