            ["Windowed"] = "Mode fen\u00EAtr\u00E9",
            ["Windows Insider Preview detected"] = "Windows Insider Preview d\u00E9tect\u00E9",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows veut d\u00E9sinstaller Center. Termine ici, ou appuie sur B pour tout garder.",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows n'a pas pu ouvrir le fichier du paquet. Le probl\u00E8me ne vient pas du paquet \u2014 le service de d\u00E9ploiement (ex\u00E9cut\u00E9 en tant que SYSTEM) n'a pas pu le lire. Installe depuis un dossier hors de ton profil utilisateur et v\u00E9rifie l'\u00E9tat de Gaming Services.",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows n'a pas pu ouvrir le paquet depuis ce dossier. Nouvelle tentative depuis un emplacement syst\u00E8me\u2026",
            ["Windows file picker"] = "S\u00E9lecteur de fichiers Windows",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). This cannot be undone \u2014 take a backup first if unsure."] = "Remet chaque r\u00E9glage ClawTweaks \u00E0 z\u00E9ro (profils, courbes, TDP, manette). Irr\u00E9versible \u2014 faites un backup avant en cas de doute.",
            ["Work down the list. Each step is optional except the last."] = "Suis la liste. Seule la derni\u00E8re \u00E9tape est obligatoire.",
            ["Working\u2026"] = "En cours\u2026",
            ["XInput controllers"] = "Manettes XInput",
