            ["not installed"] = "\uC124\uCE58\uB418\uC9C0 \uC54A\uC74C",
            ["Update available"] = "\uC5C5\uB370\uC774\uD2B8 \uC788\uC74C",
            ["Update available (beta)"] = "\uC5C5\uB370\uC774\uD2B8 \uC788\uC74C(\uBCA0\uD0C0)",
            ["Muted"] = "\uC74C\uC18C\uAC70\uB428",
            ["Checking with Windows\u2026 this can take up to a minute."] = "Windows\uC5D0 \uD655\uC778 \uC911\u2026 1\uBD84 \uC815\uB3C4 \uAC78\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["The check asks Microsoft directly and takes a moment."] = "\uC774 \uD655\uC778\uC740 Microsoft\uC5D0 \uC9C1\uC811 \uBB3C\uC5B4\uBCF4\uBBC0\uB85C \uC7A0\uC2DC \uAC78\uB9BD\uB2C8\uB2E4.",
            ["Could not check"] = "\uD655\uC778\uD560 \uC218 \uC5C6\uC74C",
            ["The answer could not be read."] = "\uC751\uB2F5\uC744 \uC77D\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.",
            ["The check failed."] = "\uD655\uC778\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4.",
