            ["Up to date"] = "\uCD5C\uC2E0 \uC0C1\uD0DC",
            ["Windows has nothing pending for this machine."] = "\uC774 PC\uC5D0 \uB300\uAE30 \uC911\uC778 Windows \uC5C5\uB370\uC774\uD2B8\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
