            ["Every week"] = "\uB9E4\uC8FC",
            ["Every {0} weeks"] = "{0}\uC8FC\uB9C8\uB2E4",
            ["Include test versions"] = "\uD14C\uC2A4\uD2B8 \uBC84\uC804 \uD3EC\uD568",
