            ["Version {0} is available."] = "\uBC84\uC804 {0}\uC744(\uB97C) \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["{0} Windows update(s) waiting"] = "Windows \uC5C5\uB370\uC774\uD2B8 {0}\uAC1C \uB300\uAE30 \uC911",
            ["No new notifications"] = "\uC0C8 \uC54C\uB9BC \uC5C6\uC74C",
            ["Gamebar Widget Releases"] = "Gamebar \uC704\uC82F \uB9B4\uB9AC\uC2A4",
            ["Check for updates and notify"] = "\uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uBC0F \uC54C\uB9BC",
            ["Windows Update"] = "Windows \uC5C5\uB370\uC774\uD2B8",
            ["Not checked automatically. You can switch this on in Center settings."] = "\uC790\uB3D9\uC73C\uB85C \uD655\uC778\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. Center \uC124\uC815\uC5D0\uC11C \uCF24 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["Checked automatically: {0}. You can change or switch this off in Center settings."] = "\uC790\uB3D9 \uD655\uC778: {0}. Center \uC124\uC815\uC5D0\uC11C \uBCC0\uACBD\uD558\uAC70\uB098 \uB04C \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["Status"] = "\uC0C1\uD0DC",
            ["Uninstall\u2026"] = "\uC81C\uAC70\u2026",
            ["Steam removes the game files"] = "Steam\uC774 \uAC8C\uC784 \uD30C\uC77C\uC744 \uC0AD\uC81C\uD569\uB2C8\uB2E4",
            ["Back to Recent"] = "\uCD5C\uADFC \uD56D\uBAA9\uC73C\uB85C",
            ["Tab visibility & order"] = "\uD0ED \uD45C\uC2DC \uBC0F \uC21C\uC11C",
            ["Favorite"] = "\uC990\uACA8\uCC3E\uAE30",
            ["Unfavorite"] = "\uC990\uACA8\uCC3E\uAE30 \uD574\uC81C",
            ["Rename\u2026"] = "\uC774\uB984 \uBC14\uAFB8\uAE30\u2026",
            ["Rename"] = "\uC774\uB984 \uBC14\uAFB8\uAE30",
            ["Remove"] = "\uC81C\uAC70",
            ["Other"] = "\uAE30\uD0C0",
            ["Recent immersive"] = "\uCD5C\uADFC \uBAB0\uC785 \uBAA8\uB4DC",
            ["OptiScaler wiki \u00B7 {0}"] = "OptiScaler \uC704\uD0A4 \u00B7 {0}",
            ["Sleep"] = "\uC808\uC804",
            ["Hibernate"] = "\uCD5C\uB300 \uC808\uC804",
            ["Launch"] = "\uC2E4\uD589",
            ["Edit"] = "\uD3B8\uC9D1",
            ["Auto pre-restore \u2014 {0}"] = "\uBCF5\uC6D0 \uC804 \uC790\uB3D9 \uBC31\uC5C5 \u2014 {0}",
            ["ClawTweaks {0} \u00B7 {1} \u00B7 {2} stores \u00B7 {3}"] = "ClawTweaks {0} \u00B7 {1} \u00B7 \uC2A4\uD1A0\uC5B4 {2}\uAC1C \u00B7 {3}",
            ["Choose a program"] = "\uD504\uB85C\uADF8\uB7A8 \uC120\uD0DD",
            ["Add"] = "\uCD94\uAC00",
            ["Add {0}"] = "{0}\uAC1C \uCD94\uAC00",
            ["Open Center"] = "Center \uC5F4\uAE30",
            ["Open Library"] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC \uC5F4\uAE30",
            ["Exit Center"] = "Center \uC885\uB8CC",
            ["The update could not install itself. Try the button below."] = "\uC5C5\uB370\uC774\uD2B8\uB97C \uC790\uB3D9\uC73C\uB85C \uC124\uCE58\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uC544\uB798 \uBC84\uD2BC\uC744 \uC0AC\uC6A9\uD558\uC138\uC694.",
            ["Installing\u2026"] = "\uC124\uCE58 \uC911\u2026",
            ["Install update now"] = "\uC9C0\uAE08 \uC5C5\uB370\uC774\uD2B8 \uC124\uCE58",
            ["Version {0} is still installed for all users, in {1}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\uBC84\uC804 {0}\uC774(\uAC00) \uC544\uC9C1 \uBAA8\uB4E0 \uC0AC\uC6A9\uC790\uC6A9\uC73C\uB85C {1}\uC5D0 \uC124\uCE58\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uBC84\uC804\uC740 \uB300\uC2E0 \uC0AC\uC6A9\uC790 \uD3F4\uB354\uC5D0 \uC124\uCE58\uB418\uBBC0\uB85C \uC774\uC804 \uBC84\uC804\uC740 \uB354 \uC774\uC0C1 \uC0AC\uC6A9\uB418\uC9C0 \uC54A\uC9C0\uB9CC, \uC81C\uAC70\uD560 \uB54C\uAE4C\uC9C0 \uC124\uC815 \u2192 \uC571\uACFC \uC2DC\uC791 \uBA54\uB274\uC5D0 \uB0A8\uC544 \uC2E4\uC218\uB85C \uC2E4\uD589\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.",
            ["A previous version is still installed for all users, in {0}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\uC774\uC804 \uBC84\uC804\uC774 \uC544\uC9C1 \uBAA8\uB4E0 \uC0AC\uC6A9\uC790\uC6A9\uC73C\uB85C {0}\uC5D0 \uC124\uCE58\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uBC84\uC804\uC740 \uB300\uC2E0 \uC0AC\uC6A9\uC790 \uD3F4\uB354\uC5D0 \uC124\uCE58\uB418\uBBC0\uB85C \uC774\uC804 \uBC84\uC804\uC740 \uB354 \uC774\uC0C1 \uC0AC\uC6A9\uB418\uC9C0 \uC54A\uC9C0\uB9CC, \uC81C\uAC70\uD560 \uB54C\uAE4C\uC9C0 \uC124\uC815 \u2192 \uC571\uACFC \uC2DC\uC791 \uBA54\uB274\uC5D0 \uB0A8\uC544 \uC2E4\uC218\uB85C \uC2E4\uD589\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below starts the old version's own uninstaller, so the prompt you see comes from it, about removing itself."] = "\uC81C\uAC70\uC5D0\uB294 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. ClawTweaks Center\uB294 \uC774\uB97C \uC694\uCCAD\uD558\uC9C0 \uC54A\uC73C\uBA70, \uC544\uB798 \uBC84\uD2BC\uC740 \uC774\uC804 \uBC84\uC804 \uC790\uCCB4\uC758 \uC81C\uAC70 \uD504\uB85C\uADF8\uB7A8\uC744 \uC2E4\uD589\uD569\uB2C8\uB2E4. \uD45C\uC2DC\uB418\uB294 \uD655\uC778 \uCC3D\uC740 \uADF8 \uD504\uB85C\uADF8\uB7A8\uC758 \uAC83\uC785\uB2C8\uB2E4.",
            ["Scroll"] = "\uC2A4\uD06C\uB864",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller still won't start."] = "\uCEE4\uB110 \uB4DC\uB77C\uC774\uBC84\uB97C \uC124\uCE58\uD569\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uC791\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC124\uCE58\uB41C \uAC83\uCC98\uB7FC \uBCF4\uC5EC\uB3C4 \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uC2DC\uC791\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["Version {0}"] = "\uBC84\uC804 {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "\uC0C8 ClawTweaks Center\uB294 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC774 \uD544\uC694 \uC5C6\uACE0 \uB2E4\uB978 \uC704\uCE58\uC5D0 \uC124\uCE58\uB429\uB2C8\uB2E4.",
            ["No Xbox games are registered for this account."] = "\uC774 \uACC4\uC815\uC5D0 \uB4F1\uB85D\uB41C Xbox \uAC8C\uC784\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["No ROMs for {0}."] = "{0} ROM\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["Cycle"] = "\uC804\uD658",
            ["checking the installed version\u2026"] = "\uC124\uCE58\uB41C \uBC84\uC804 \uD655\uC778 \uC911\u2026",
            ["you have {0}."] = "\uD604\uC7AC {0}\uC785\uB2C8\uB2E4.",
            ["Requires ClawTweaks {0} or newer"] = "ClawTweaks {0} \uC774\uC0C1 \uD544\uC694",
            ["Reset, Backup and Restore need ClawTweaks {0} (or 0.1.8+) \u2014 {1} Update ClawTweaks from \"Update & Release\" first."] = "\uCD08\uAE30\uD654, \uBC31\uC5C5, \uBCF5\uC6D0\uC5D0\uB294 ClawTweaks {0}(\uB610\uB294 0.1.8+)\uC774 \uD544\uC694\uD569\uB2C8\uB2E4 \u2014 {1} \uBA3C\uC800 \"Update & Release\"\uC5D0\uC11C ClawTweaks\uB97C \uC5C5\uB370\uC774\uD2B8\uD558\uC138\uC694.",
            ["Unknown error."] = "\uC54C \uC218 \uC5C6\uB294 \uC624\uB958.",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "\uBC31\uC5C5 \uBCF5\uC6D0 \uC911 \u2014 \uC644\uB8CC\uB418\uBA74 \uD5EC\uD37C\uAC00 \uB2E4\uC2DC \uC2DC\uC791\uB429\uB2C8\uB2E4\u2026",
            ["Restore likely completed"] = "\uBCF5\uC6D0\uC774 \uC644\uB8CC\uB41C \uAC83 \uAC19\uC2B5\uB2C8\uB2E4",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "\uD5EC\uD37C\uAC00 \uD655\uC778 \uC804\uC5D0 \uB2E4\uC2DC \uC2DC\uC791\uB418\uC5C8\uC2B5\uB2C8\uB2E4. Game Bar(Win+G)\uB97C \uB2E4\uC2DC \uC5F4\uC5B4 \uD504\uB85C\uD544\uC744 \uD655\uC778\uD558\uC138\uC694 \u2014 \uC774\uC0C1\uD558\uBA74 \uC790\uB3D9 \uC0AC\uC804 \uBC31\uC5C5\uC744 \uBCF5\uC6D0\uD558\uC138\uC694.",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "\uC774 ZIP\uC5D0\uB294 \uC720\uD6A8\uD55C ClawTweaks \uB9E4\uB2C8\uD398\uC2A4\uD2B8\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4 \u2014 \uC2E4\uC81C \uBC31\uC5C5\uC774 \uC544\uB2C8\uBA74 \uD5EC\uD37C\uAC00 \uAC70\uBD80\uD569\uB2C8\uB2E4.",
            ["Different ClawTweaks version"] = "\uB2E4\uB978 ClawTweaks \uBC84\uC804",
            ["Supported."] = "\uC9C0\uC6D0\uB428.",
            ["Recognized, but not supported yet."] = "\uC778\uC2DD\uB418\uC5C8\uC9C0\uB9CC \uC544\uC9C1 \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["Not a recognized MSI Claw \u2014 installing here is untested."] = "\uC778\uC2DD\uB41C MSI Claw\uAC00 \uC544\uB2D9\uB2C8\uB2E4 \u2014 \uC5EC\uAE30\uC11C\uC758 \uC124\uCE58\uB294 \uD14C\uC2A4\uD2B8\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["Install the missing prerequisites"] = "\uB204\uB77D\uB41C \uD544\uC218 \uAD6C\uC131 \uC694\uC18C \uC124\uCE58",
            ["Download each one from the vendor and run their installer, then re-check."] = "\uAC01\uAC01 \uC81C\uC870\uC0AC\uC5D0\uC11C \uB0B4\uB824\uBC1B\uC544 \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC744 \uC2E4\uD589\uD55C \uB4A4 \uB2E4\uC2DC \uD655\uC778\uD558\uC138\uC694.",
            ["Re-check and continue"] = "\uB2E4\uC2DC \uD655\uC778\uD558\uACE0 \uACC4\uC18D",
            ["Re-check tools"] = "\uB3C4\uAD6C \uB2E4\uC2DC \uD655\uC778",
            ["Trust the ClawTweaks signing certificate"] = "ClawTweaks \uC11C\uBA85 \uC778\uC99D\uC11C \uC2E0\uB8B0",
            ["ClawTweaks is signed with its own certificate, and Windows only installs a package whose certificate it trusts. You only have to do this once \u2014 every future build uses the same one."] = "ClawTweaks\uB294 \uC790\uCCB4 \uC778\uC99D\uC11C\uB85C \uC11C\uBA85\uB418\uC5B4 \uC788\uC73C\uBA70, Windows\uB294 \uC2E0\uB8B0\uD558\uB294 \uC778\uC99D\uC11C\uC758 \uD328\uD0A4\uC9C0\uB9CC \uC124\uCE58\uD569\uB2C8\uB2E4. \uD55C \uBC88\uB9CC \uD558\uBA74 \uB429\uB2C8\uB2E4 \u2014 \uC774\uD6C4 \uBAA8\uB4E0 \uBE4C\uB4DC\uAC00 \uAC19\uC740 \uC778\uC99D\uC11C\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
            ["The certificate was imported for your user account instead of the local machine. Windows only consults the machine store when installing a package, so this has no effect. Run the import again and pick \"Local Machine\" on the first page."] = "\uC778\uC99D\uC11C\uAC00 \uB85C\uCEEC \uCEF4\uD4E8\uD130\uAC00 \uC544\uB2CC \uC0AC\uC6A9\uC790 \uACC4\uC815\uC5D0 \uAC00\uC838\uC640\uC84C\uC2B5\uB2C8\uB2E4. Windows\uB294 \uD328\uD0A4\uC9C0\uB97C \uC124\uCE58\uD560 \uB54C \uCEF4\uD4E8\uD130 \uC800\uC7A5\uC18C\uB9CC \uD655\uC778\uD558\uBBC0\uB85C \uD6A8\uACFC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uAC00\uC838\uC624\uAE30\uB97C \uB2E4\uC2DC \uC2E4\uD589\uD558\uACE0 \uCCAB \uD398\uC774\uC9C0\uC5D0\uC11C \"\uB85C\uCEEC \uCEF4\uD4E8\uD130\"\uB97C \uC120\uD0DD\uD558\uC138\uC694.",
            ["The certificate landed in \"Trusted Root Certification Authorities\". That is both more than ClawTweaks needs \u2014 it would make this certificate a trust anchor for anything, not just this package \u2014 and still not where Windows looks. Remove it from there and import it into \"Trusted People\" instead."] = "\uC778\uC99D\uC11C\uAC00 \"\uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uB8E8\uD2B8 \uC778\uC99D \uAE30\uAD00\"\uC5D0 \uB4E4\uC5B4\uAC14\uC2B5\uB2C8\uB2E4. \uC774\uB294 ClawTweaks\uC5D0 \uD544\uC694\uD55C \uAC83 \uC774\uC0C1\uC774\uBA70 \u2014 \uC774 \uD328\uD0A4\uC9C0\uBFD0 \uC544\uB2C8\uB77C \uBAA8\uB4E0 \uAC83\uC758 \uC2E0\uB8B0 \uC575\uCEE4\uAC00 \uB429\uB2C8\uB2E4 \u2014 \uADF8\uB7EC\uBA74\uC11C\uB3C4 Windows\uAC00 \uD655\uC778\uD558\uB294 \uC704\uCE58\uAC00 \uC544\uB2D9\uB2C8\uB2E4. \uAC70\uAE30\uC11C \uC81C\uAC70\uD558\uACE0 \uB300\uC2E0 \"\uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uC0AC\uC6A9\uC790\"\uC5D0 \uAC00\uC838\uC624\uC138\uC694.",
            ["Check the certificate and continue"] = "\uC778\uC99D\uC11C \uD655\uC778 \uD6C4 \uACC4\uC18D",
            ["Check certificate"] = "\uC778\uC99D\uC11C \uD655\uC778",
            ["Installed, but the helper did not appear in time \u2014 open the Game Bar (Win+G) manually."] = "\uC124\uCE58\uB418\uC5C8\uC9C0\uB9CC \uD5EC\uD37C\uAC00 \uC81C\uB54C \uB098\uD0C0\uB098\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4 \u2014 Game Bar(Win+G)\uB97C \uC9C1\uC811 \uC5EC\uC138\uC694.",
            ["Virtual pad"] = "\uAC00\uC0C1 \uD328\uB4DC",
            ["Virtual controller mode detected"] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC \uBAA8\uB4DC \uAC10\uC9C0\uB428",
            ["{0} active and running."] = "{0} \uD65C\uC131 \uC0C1\uD0DC\uB85C \uC2E4\uD589 \uC911.",
            ["HW controller mode detected"] = "HW \uCEE8\uD2B8\uB864\uB7EC \uBAA8\uB4DC \uAC10\uC9C0\uB428",
            ["MSI HW Controller active and running."] = "MSI HW \uCEE8\uD2B8\uB864\uB7EC \uD65C\uC131 \uC0C1\uD0DC\uB85C \uC2E4\uD589 \uC911.",
            ["Claw controller not detected."] = "Claw \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uAC10\uC9C0\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["Controller mode unknown"] = "\uCEE8\uD2B8\uB864\uB7EC \uBAA8\uB4DC \uC54C \uC218 \uC5C6\uC74C",
            ["The download did not complete. Check your internet connection and try again."] = "\uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC644\uB8CC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC778\uD130\uB137 \uC5F0\uACB0\uC744 \uD655\uC778\uD558\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
            ["This version has no package to download."] = "\uC774 \uBC84\uC804\uC5D0\uB294 \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uD328\uD0A4\uC9C0\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["Download complete."] = "\uB2E4\uC6B4\uB85C\uB4DC \uC644\uB8CC.",
            ["The download contains no package file."] = "\uB2E4\uC6B4\uB85C\uB4DC\uC5D0 \uD328\uD0A4\uC9C0 \uD30C\uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The downloaded package is incomplete \u2014 its manifest is missing."] = "\uB2E4\uC6B4\uB85C\uB4DC\uD55C \uD328\uD0A4\uC9C0\uAC00 \uBD88\uC644\uC804\uD569\uB2C8\uB2E4 \u2014 \uB9E4\uB2C8\uD398\uC2A4\uD2B8\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The downloaded package is not readable."] = "\uB2E4\uC6B4\uB85C\uB4DC\uD55C \uD328\uD0A4\uC9C0\uB97C \uC77D\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["(received {0:N0} of {1:N0} bytes)"] = "({1:N0} \uC911 {0:N0}\uBC14\uC774\uD2B8 \uC218\uC2E0)",
            ["The download produced an empty file."] = "\uB2E4\uC6B4\uB85C\uB4DC \uACB0\uACFC \uBE48 \uD30C\uC77C\uC774 \uC0DD\uC131\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
            ["Click \"Install Certificate\u2026\" on the General tab."] = "\uC77C\uBC18 \uD0ED\uC5D0\uC11C \"\uC778\uC99D\uC11C \uC124\uCE58\u2026\"\uB97C \uD074\uB9AD\uD558\uC138\uC694.",
            ["Store Location: choose \"Local Machine\" (not \"Current User\"), then Next. Windows asks for administrator rights here \u2014 that prompt comes from Windows itself."] = "\uC800\uC7A5\uC18C \uC704\uCE58: \"\uB85C\uCEEC \uCEF4\uD4E8\uD130\"\uB97C \uC120\uD0DD\uD558\uACE0(\"\uD604\uC7AC \uC0AC\uC6A9\uC790\" \uC544\uB2D8) \uB2E4\uC74C\uC744 \uB204\uB974\uC138\uC694. \uC5EC\uAE30\uC11C Windows\uAC00 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4 \u2014 \uC774 \uBA54\uC2DC\uC9C0\uB294 Windows \uC790\uCCB4\uC5D0\uC11C \uB098\uC635\uB2C8\uB2E4.",
            ["Choose \"Place all certificates in the following store\", click Browse\u2026"] = "\"\uBAA8\uB4E0 \uC778\uC99D\uC11C\uB97C \uB2E4\uC74C \uC800\uC7A5\uC18C\uC5D0 \uC800\uC7A5\"\uC744 \uC120\uD0DD\uD558\uACE0 \uCC3E\uC544\uBCF4\uAE30\u2026\uB97C \uD074\uB9AD\uD558\uC138\uC694.",
            ["Select \"Trusted People\" \u2014 NOT \"Trusted Root Certification Authorities\"."] = "\"\uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uC0AC\uC6A9\uC790\"\uB97C \uC120\uD0DD\uD558\uC138\uC694 \u2014 \"\uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uB8E8\uD2B8 \uC778\uC99D \uAE30\uAD00\"\uC774 \uC544\uB2D9\uB2C8\uB2E4.",
            ["Next, then Finish. You should see \"The import was successful.\""] = "\uB2E4\uC74C, \uADF8\uB2E4\uC74C \uB9C8\uCE68. \"\uAC00\uC838\uC624\uAE30\uB97C \uC644\uB8CC\uD588\uC2B5\uB2C8\uB2E4.\"\uAC00 \uD45C\uC2DC\uB418\uC5B4\uC57C \uD569\uB2C8\uB2E4.",
            ["Controller probe timed out."] = "\uCEE8\uD2B8\uB864\uB7EC \uD655\uC778 \uC2DC\uAC04 \uCD08\uACFC.",
            ["Controller probe failed: {0}"] = "\uCEE8\uD2B8\uB864\uB7EC \uD655\uC778 \uC2E4\uD328: {0}",
            ["MSI Claw controller not detected (VID_0DB0). Connect/enable the controller, or MSI Center M may have taken it over."] = "MSI Claw \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uAC10\uC9C0\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4(VID_0DB0). \uCEE8\uD2B8\uB864\uB7EC\uB97C \uC5F0\uACB0/\uD65C\uC131\uD654\uD558\uC138\uC694. MSI Center M\uC774 \uAC00\uC838\uAC14\uC744 \uC218\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.",
            ["MSI Center M is running. It can fight ClawTweaks for the controller and LED. This is handled after installation."] = "MSI Center M\uC774 \uC2E4\uD589 \uC911\uC785\uB2C8\uB2E4. \uCEE8\uD2B8\uB864\uB7EC\uC640 LED\uB97C \uB450\uACE0 ClawTweaks\uC640 \uCDA9\uB3CC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC124\uCE58 \uD6C4\uC5D0 \uCC98\uB9AC\uB429\uB2C8\uB2E4.",
            ["Steam's Xbox controller filter driver is present \u2014 a common cause of double input. Check Steam Input settings if you see doubled inputs."] = "Steam\uC758 Xbox \uCEE8\uD2B8\uB864\uB7EC \uD544\uD130 \uB4DC\uB77C\uC774\uBC84\uAC00 \uC788\uC2B5\uB2C8\uB2E4 \u2014 \uC774\uC911 \uC785\uB825\uC758 \uD754\uD55C \uC6D0\uC778\uC785\uB2C8\uB2E4. \uC785\uB825\uC774 \uC911\uBCF5\uB418\uBA74 Steam \uC785\uB825 \uC124\uC815\uC744 \uD655\uC778\uD558\uC138\uC694.",
            ["{0} XInput controllers are currently visible. Two or more while playing = double input."] = "\uD604\uC7AC XInput \uCEE8\uD2B8\uB864\uB7EC {0}\uAC1C\uAC00 \uBCF4\uC785\uB2C8\uB2E4. \uD50C\uB808\uC774 \uC911 2\uAC1C \uC774\uC0C1 = \uC774\uC911 \uC785\uB825.",
            ["Controller healthy \u2014 ready to mount as a virtual pad."] = "\uCEE8\uD2B8\uB864\uB7EC \uC815\uC0C1 \u2014 \uAC00\uC0C1 \uD328\uB4DC\uB85C \uC5F0\uACB0\uD560 \uC900\uBE44\uAC00 \uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
            ["MSI Claw controller not found. Connect/enable it (MSI Center M may hold it)."] = "MSI Claw \uCEE8\uD2B8\uB864\uB7EC\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC5F0\uACB0/\uD65C\uC131\uD654\uD558\uC138\uC694(MSI Center M\uC774 \uC810\uC720 \uC911\uC77C \uC218 \uC788\uC74C).",
            ["Controller HID is held by another process \u2014 close conflicting controller software and re-check."] = "\uB2E4\uB978 \uD504\uB85C\uC138\uC2A4\uAC00 \uCEE8\uD2B8\uB864\uB7EC HID\uB97C \uC810\uC720 \uC911\uC785\uB2C8\uB2E4 \u2014 \uCDA9\uB3CC\uD558\uB294 \uCEE8\uD2B8\uB864\uB7EC \uC18C\uD504\uD2B8\uC6E8\uC5B4\uB97C \uB2EB\uACE0 \uB2E4\uC2DC \uD655\uC778\uD558\uC138\uC694.",
            ["Controller HID opened but did not respond \u2014 try re-checking; a reboot may be needed."] = "\uCEE8\uD2B8\uB864\uB7EC HID\uAC00 \uC5F4\uB838\uC9C0\uB9CC \uC751\uB2F5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4 \u2014 \uB2E4\uC2DC \uD655\uC778\uD558\uC138\uC694. \uC7AC\uBD80\uD305\uC774 \uD544\uC694\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["Could not determine controller health."] = "\uCEE8\uD2B8\uB864\uB7EC \uC0C1\uD0DC\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The helper did not answer the health probe."] = "\uD5EC\uD37C\uAC00 \uC0C1\uD0DC \uD655\uC778\uC5D0 \uC751\uB2F5\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["Unknown device"] = "\uC54C \uC218 \uC5C6\uB294 \uC7A5\uCE58",
            ["Could not locate the installed package \u2014 helper files not deployed."] = "\uC124\uCE58\uB41C \uD328\uD0A4\uC9C0\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4 \u2014 \uD5EC\uD37C \uD30C\uC77C\uC774 \uBC30\uD3EC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["Helper files were not deployed \u2014 the widget will retry when it starts the helper."] = "\uD5EC\uD37C \uD30C\uC77C\uC774 \uBC30\uD3EC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4 \u2014 \uC704\uC82F\uC774 \uD5EC\uD37C\uB97C \uC2DC\uC791\uD560 \uB54C \uB2E4\uC2DC \uC2DC\uB3C4\uD569\uB2C8\uB2E4.",
            ["The helper is not answering."] = "\uD5EC\uD37C\uAC00 \uC751\uB2F5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["A backup of your settings is at {0}"] = "\uC124\uC815 \uBC31\uC5C5 \uC704\uCE58: {0}",
            ["Could not connect to the helper."] = "\uD5EC\uD37C\uC5D0 \uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The helper did not respond in time."] = "\uD5EC\uD37C\uAC00 \uC81C\uB54C \uC751\uB2F5\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["Disabling\u2026"] = "\uBE44\uD65C\uC131\uD654 \uC911\u2026",
            ["Disabled."] = "\uBE44\uD65C\uC131\uD654\uB428.",
            ["Enabling\u2026"] = "\uD65C\uC131\uD654 \uC911\u2026",
            ["Enabled and verified ({0})."] = "\uD65C\uC131\uD654 \uBC0F \uD655\uC778\uB428({0}).",
            ["virtual pad"] = "\uAC00\uC0C1 \uD328\uB4DC",
            ["Hides the physical gamepad so games see only the virtual controller."] = "\uAC8C\uC784\uC774 \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uB9CC \uBCF4\uB3C4\uB85D \uC2E4\uC81C \uAC8C\uC784\uD328\uB4DC\uB97C \uC228\uAE41\uB2C8\uB2E4.",
            ["Take HidHide_x.x.x.x_x64.exe."] = "HidHide_x.x.x.x_x64.exe\uB97C \uBC1B\uC73C\uC138\uC694.",
            ["Provides the virtual controller itself (the VIIPER backend)."] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC \uC790\uCCB4\uB97C \uC81C\uACF5\uD569\uB2C8\uB2E4(VIIPER \uBC31\uC5D4\uB4DC).",
            ["Take USBip-0.9.8.0-x64.exe from this page. The link opens version 0.9.8.0 deliberately \u2014 it is the version ClawTweaks supports."] = "\uC774 \uD398\uC774\uC9C0\uC5D0\uC11C USBip-0.9.8.0-x64.exe\uB97C \uBC1B\uC73C\uC138\uC694. \uB9C1\uD06C\uB294 \uC758\uB3C4\uC801\uC73C\uB85C 0.9.8.0 \uBC84\uC804\uC744 \uC5FD\uB2C8\uB2E4 \u2014 ClawTweaks\uAC00 \uC9C0\uC6D0\uD558\uB294 \uBC84\uC804\uC785\uB2C8\uB2E4.",
            ["Do not download the ARM version, and do not take an older usbip release: below 0.9.8.0 the device blue-screens while the virtual controller runs."] = "ARM \uBC84\uC804\uC774\uB098 \uC774\uC804 usbip \uB9B4\uB9AC\uC2A4\uB97C \uBC1B\uC9C0 \uB9C8\uC138\uC694: 0.9.8.0 \uBBF8\uB9CC\uC5D0\uC11C\uB294 \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC \uC2E4\uD589 \uC911 \uBE14\uB8E8\uC2A4\uD06C\uB9B0\uC774 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.",
            ["Applies the per-game FPS cap and draws the on-screen display."] = "\uAC8C\uC784\uBCC4 FPS \uC81C\uD55C\uC744 \uC801\uC6A9\uD558\uACE0 \uC628\uC2A4\uD06C\uB9B0 \uB514\uC2A4\uD50C\uB808\uC774\uB97C \uADF8\uB9BD\uB2C8\uB2E4.",
            ["Take RivaTuner Statistics Server."] = "RivaTuner Statistics Server\uB97C \uBC1B\uC73C\uC138\uC694.",
            ["Reads the CPU sensors ClawTweaks shows in the widget."] = "ClawTweaks\uAC00 \uC704\uC82F\uC5D0 \uD45C\uC2DC\uD558\uB294 CPU \uC13C\uC11C\uB97C \uC77D\uC2B5\uB2C8\uB2E4.",
            ["Take PawnIO Setup."] = "PawnIO Setup\uC744 \uBC1B\uC73C\uC138\uC694.",
            ["This ClawTweaks Center build is outdated. Please download the latest build."] = "\uC774 ClawTweaks Center \uBE4C\uB4DC\uB294 \uC624\uB798\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uCD5C\uC2E0 \uBE4C\uB4DC\uB97C \uB0B4\uB824\uBC1B\uC73C\uC138\uC694.",
            ["{0} (running {1}, needs {2}+)"] = "{0} (\uC2E4\uD589 \uC911 {1}, \uD544\uC694 {2}+)",
            ["Test build"] = "\uD14C\uC2A4\uD2B8 \uBE4C\uB4DC",
            ["Release"] = "\uC815\uC2DD \uBC84\uC804",
            ["Nightly"] = "\uB098\uC774\uD2C0\uB9AC",
            ["BROKEN: leftover registry entries but no driver binary \u2014 reinstall and reboot"] = "\uC190\uC0C1\uB428: \uB808\uC9C0\uC2A4\uD2B8\uB9AC \uD56D\uBAA9\uB9CC \uB0A8\uACE0 \uB4DC\uB77C\uC774\uBC84 \uD30C\uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4 \u2014 \uB2E4\uC2DC \uC124\uCE58\uD558\uACE0 \uC7AC\uBD80\uD305\uD558\uC138\uC694",
            ["BROKEN: usbip's files are installed but its driver is not registered \u2014 the installer's driver step (devnode.exe) failed. The usual cause is the -arm64 download, which the release page lists above the x64 one. Uninstall usbip, re-run the installer whose name ends in -x64.exe, and reboot."] = "\uC190\uC0C1\uB428: usbip \uD30C\uC77C\uC740 \uC124\uCE58\uB418\uC5C8\uC9C0\uB9CC \uB4DC\uB77C\uC774\uBC84\uAC00 \uB4F1\uB85D\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4 \u2014 \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC758 \uB4DC\uB77C\uC774\uBC84 \uB2E8\uACC4(devnode.exe)\uAC00 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4. \uD754\uD55C \uC6D0\uC778\uC740 \uB9B4\uB9AC\uC2A4 \uD398\uC774\uC9C0\uC5D0\uC11C x64 \uC704\uC5D0 \uD45C\uC2DC\uB418\uB294 -arm64 \uB2E4\uC6B4\uB85C\uB4DC\uC785\uB2C8\uB2E4. usbip\uC744 \uC81C\uAC70\uD558\uACE0 \uC774\uB984\uC774 -x64.exe\uB85C \uB05D\uB098\uB294 \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC744 \uB2E4\uC2DC \uC2E4\uD589\uD55C \uB4A4 \uC7AC\uBD80\uD305\uD558\uC138\uC694.",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Older versions crash the device with a blue screen while the virtual controller is running, so ClawTweaks will not start it. Run the ClawTweaks setup, or install {1} from the link on this page, and reboot."] = "\uC9C0\uC6D0\uB418\uC9C0 \uC54A\uB294 \uBC84\uC804: usbip {0}\uC774(\uAC00) \uC124\uCE58\uB418\uC5B4 \uC788\uC9C0\uB9CC ClawTweaks\uC5D0\uB294 {1}\uC774(\uAC00) \uD544\uC694\uD569\uB2C8\uB2E4. \uC774\uC804 \uBC84\uC804\uC740 \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC \uC2E4\uD589 \uC911 \uBE14\uB8E8\uC2A4\uD06C\uB9B0\uC744 \uC77C\uC73C\uD0A4\uBBC0\uB85C ClawTweaks\uAC00 \uC2DC\uC791\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. ClawTweaks \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC744 \uC2E4\uD589\uD558\uAC70\uB098 \uC774 \uD398\uC774\uC9C0\uC758 \uB9C1\uD06C\uC5D0\uC11C {1}\uC744(\uB97C) \uC124\uCE58\uD55C \uB4A4 \uC7AC\uBD80\uD305\uD558\uC138\uC694.",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Uninstall usbip, install {1} from the link on this page, and reboot."] = "\uC9C0\uC6D0\uB418\uC9C0 \uC54A\uB294 \uBC84\uC804: usbip {0}\uC774(\uAC00) \uC124\uCE58\uB418\uC5B4 \uC788\uC9C0\uB9CC ClawTweaks\uC5D0\uB294 {1}\uC774(\uAC00) \uD544\uC694\uD569\uB2C8\uB2E4. usbip\uC744 \uC81C\uAC70\uD558\uACE0 \uC774 \uD398\uC774\uC9C0\uC758 \uB9C1\uD06C\uC5D0\uC11C {1}\uC744(\uB97C) \uC124\uCE58\uD55C \uB4A4 \uC7AC\uBD80\uD305\uD558\uC138\uC694.",
