            ["Version {0}"] = "Versi\u00F3n {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "El nuevo ClawTweaks Center no necesita permisos de administrador y se instala en otra ubicaci\u00F3n.",
