            ["Unknown error."] = "Error desconocido.",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "Restaurando la copia \u2014 el helper se reiniciar\u00E1 al terminar\u2026",
            ["Restore likely completed"] = "Restauraci\u00F3n probablemente completada",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "El helper se reinici\u00F3 antes de confirmar. Vuelve a abrir la Game Bar (Win+G) y revisa tus perfiles \u2014 si algo falla, restaura la copia autom\u00E1tica previa.",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "Este ZIP no tiene un manifiesto ClawTweaks v\u00E1lido \u2014 el helper lo rechazar\u00E1 si no es una copia real.",
            ["Different ClawTweaks version"] = "Otra versi\u00F3n de ClawTweaks",
